-- Article 4: the six passages from the book as its pages (Ronit, 2026-10-27).
-- Each scan block gets its pages: the image of the whole page (paper and
-- the spine's shadow all over it, the ink outside the passage lighter), its
-- page number, and where the gold line stands (% of the page's height).
-- Scenes 2 and 4 run over two pages and show as a spread. Scene 6 is the end
-- of scene 5's paragraph: both are on page 156, each with only its own
-- words in full ink. The images are in /assets/article/a04-scan-*.webp
-- (deployed with this). The passage's text stays in the block as the
-- scan's description for screen readers.
--
-- Touches the six scan blocks only; if any is not exactly as expected, UPDATE 0.
-- Fixed 2026-10-27: the first version matched the blocks as they would be
-- AFTER the change, so it changed nothing (UPDATE 0).

UPDATE articles SET
  blocks = (
    SELECT jsonb_agg(
      CASE
      WHEN e = $o1${"type": "scan", "src": "", "alt": "", "credit": "", "text": "צהריים. יפתח בוכה. יפתח אף פעם לא בוכה. אם הוא בוכה, סימן שזה ממש כואב. רות'קה ממהרת אלינו, לירידה הגדולה שליד הַחֲדַרוֹכֶל. קראנו לה הכי מהר שיכולנו. שלחנו את עמיר, הוא רץ הכי מהר מכולנו. לרות'קה יש ידיים חזקות, היא תיקח את יפתח עד לַבֵּיתֶלָדִים. שתי הברכיים שלו מלאות דם. הוא נמרח ממש חזק.\n\nאין אחד מאיתנו שאין לו את הסימן הקטן בתחתית של הסנטר, כולנו פתחנו אותו מתישהו, לפני שיכולנו לזכור. זה הכי רגיל אצלנו להסתובב עם חתך, שריטה או גלד מחלים שמתקלף קצת או הרבה. כשאנחנו נופלים או נשרטים, רות'קה אומרת שזה לא סוף העולם. אנחנו נפצעים כל הזמן, אבל זה אף פעם לא סוף העולם, גם לא כשיורדת האצבע.", "source": "(מתוך ״עיניים גדולות זה לא טוב״, הוצאת מטר)"}$o1$::jsonb THEN $n1${"type": "scan", "src": "", "alt": "", "credit": "", "text": "צהריים. יפתח בוכה. יפתח אף פעם לא בוכה. אם הוא בוכה, סימן שזה ממש כואב. רות'קה ממהרת אלינו, לירידה הגדולה שליד הַחֲדַרוֹכֶל. קראנו לה הכי מהר שיכולנו. שלחנו את עמיר, הוא רץ הכי מהר מכולנו. לרות'קה יש ידיים חזקות, היא תיקח את יפתח עד לַבֵּיתֶלָדִים. שתי הברכיים שלו מלאות דם. הוא נמרח ממש חזק.\n\nאין אחד מאיתנו שאין לו את הסימן הקטן בתחתית של הסנטר, כולנו פתחנו אותו מתישהו, לפני שיכולנו לזכור. זה הכי רגיל אצלנו להסתובב עם חתך, שריטה או גלד מחלים שמתקלף קצת או הרבה. כשאנחנו נופלים או נשרטים, רות'קה אומרת שזה לא סוף העולם. אנחנו נפצעים כל הזמן, אבל זה אף פעם לא סוף העולם, גם לא כשיורדת האצבע.", "source": "(מתוך ״עיניים גדולות זה לא טוב״, הוצאת מטר)", "pages": [{"page": 154, "src": "/assets/article/a04-scan-1-p154.webp", "w": 725, "h": 1244, "mark": [37.82, 73.11]}]}$n1$::jsonb
      WHEN e = $o2${"type": "scan", "src": "", "alt": "", "credit": "", "text": "רות'קה מרימה את יפתח. רות'קה לא נבהלת. היא לא מפחדת משום דבר, גם לא מהקצף של הביצים. כשהיא מכינה לנו קצפיות, שכל כך נעים לשבור בפה, אנחנו מסתכלים איך היא מערבבת לתוך הבלילה את הקצף, שהיא קוראת לו \"מרנג\". הידיים שלה עובדות כמו כשהיא מובילה אותנו למקלחות אחרי ארוחת צהריים — מהר ובביטחון. רות'קה אומרת ש\"לא צריך לפחד מהקצף!\" וצוחקת. אמא אומרת שקצף לא מערבבים. מקפלים. אמא מקפלת את הקצף לאט ובזהירות. כשאני אקפל קצף אני אערבב אותו כמו רות'קה כי אני לא פחדנית."}$o2$::jsonb THEN $n2${"type": "scan", "src": "", "alt": "", "credit": "", "text": "רות'קה מרימה את יפתח. רות'קה לא נבהלת. היא לא מפחדת משום דבר, גם לא מהקצף של הביצים. כשהיא מכינה לנו קצפיות, שכל כך נעים לשבור בפה, אנחנו מסתכלים איך היא מערבבת לתוך הבלילה את הקצף, שהיא קוראת לו \"מרנג\". הידיים שלה עובדות כמו כשהיא מובילה אותנו למקלחות אחרי ארוחת צהריים — מהר ובביטחון. רות'קה אומרת ש\"לא צריך לפחד מהקצף!\" וצוחקת. אמא אומרת שקצף לא מערבבים. מקפלים. אמא מקפלת את הקצף לאט ובזהירות. כשאני אקפל קצף אני אערבב אותו כמו רות'קה כי אני לא פחדנית.", "pages": [{"page": 154, "src": "/assets/article/a04-scan-2-p154.webp", "w": 725, "h": 1244, "mark": [73.11, 90.88]}, {"page": 155, "src": "/assets/article/a04-scan-2-p155.webp", "w": 725, "h": 1244, "mark": [11.9, 23.95]}]}$n2$::jsonb
      WHEN e = $o3${"type": "scan", "src": "", "alt": "", "credit": "", "text": "אנחנו מתקרבים לַבֵּיתֶלָדִים. רות'קה אומרת שזה שום דבר, לא לעשות עניין. יפתח אפילו לא נאנח, רק שני שבילים שכבר בקושי אפשר לראות על הלחיים המזיעות שלו נשארו מהדמעות שכבר נעלמו. גם אני מנסה בדרך כלל לא לבכות, אבל אני לא מצליחה כמו יפתח. גם גילי ונועם יותר טובים ממני בלא לבכות. הם מאוד חזקים ולא בכיינים, וכשאגדל גם אני אהיה חזקה כמוהם. זה לא כל כך חשוב מה אנחנו מרגישים באמת, חשוב מה רואים.\n\nכשגילי או נועם מגיעים הביתה פצועים, הם אף פעם לא צריכים שאמא תרגיע אותם. הם מגיעים רגועים. אני מסתכלת על יפתח ויודעת ששורף לו ממש, אפילו שכבר לא בורחות לו דמעות. גם כשבורחות לנו דמעות, אנחנו משתדלים לא לבכות בקול. אנחנו לא מפונקים. ליאת בוכה בקול, ואנחנו קוראים לה יללנית. רות'קה אומרת שזה לא סוף העולם. אז מתי מותר שכואב יהיה סוף העולם?"}$o3$::jsonb THEN $n3${"type": "scan", "src": "", "alt": "", "credit": "", "text": "אנחנו מתקרבים לַבֵּיתֶלָדִים. רות'קה אומרת שזה שום דבר, לא לעשות עניין. יפתח אפילו לא נאנח, רק שני שבילים שכבר בקושי אפשר לראות על הלחיים המזיעות שלו נשארו מהדמעות שכבר נעלמו. גם אני מנסה בדרך כלל לא לבכות, אבל אני לא מצליחה כמו יפתח. גם גילי ונועם יותר טובים ממני בלא לבכות. הם מאוד חזקים ולא בכיינים, וכשאגדל גם אני אהיה חזקה כמוהם. זה לא כל כך חשוב מה אנחנו מרגישים באמת, חשוב מה רואים.\n\nכשגילי או נועם מגיעים הביתה פצועים, הם אף פעם לא צריכים שאמא תרגיע אותם. הם מגיעים רגועים. אני מסתכלת על יפתח ויודעת ששורף לו ממש, אפילו שכבר לא בורחות לו דמעות. גם כשבורחות לנו דמעות, אנחנו משתדלים לא לבכות בקול. אנחנו לא מפונקים. ליאת בוכה בקול, ואנחנו קוראים לה יללנית. רות'קה אומרת שזה לא סוף העולם. אז מתי מותר שכואב יהיה סוף העולם?", "pages": [{"page": 155, "src": "/assets/article/a04-scan-3-p155.webp", "w": 725, "h": 1244, "mark": [23.95, 67.04]}]}$n3$::jsonb
      WHEN e = $o4${"type": "scan", "src": "", "alt": "", "credit": "", "text": "פעם אחת בכיתי ממש. נדב זרק עלַי עלִי של מכתש מהפִּינַטֶבַע. העלי פגע בי בפנים, כמעט בתוך העין. רות'קה רצה איתי למרפאה, סחבה אותי על הידיים. קראו לאמא מהמוסד. חנה בחלוק הלבן והנעליים המצחיקות אמרה לי להתאפק ולא לבכות, כי העין נקרעה והבכי יגדיל את הפצע. החזקתי את הדמעות בתוך העיניים עד שההסעה הגיעה ואמא נכנסה למרפאה. כשראיתי את אמא הדמעות ירדו. עשו לי תפרים ורות'קה אומרת שמזל שנשארה לי עין. עכשיו יש לי גם את הסימן הקטן של כולנו בסנטר וגם סימן מתחת לעין. אני מיוחדת."}$o4$::jsonb THEN $n4${"type": "scan", "src": "", "alt": "", "credit": "", "text": "פעם אחת בכיתי ממש. נדב זרק עלַי עלִי של מכתש מהפִּינַטֶבַע. העלי פגע בי בפנים, כמעט בתוך העין. רות'קה רצה איתי למרפאה, סחבה אותי על הידיים. קראו לאמא מהמוסד. חנה בחלוק הלבן והנעליים המצחיקות אמרה לי להתאפק ולא לבכות, כי העין נקרעה והבכי יגדיל את הפצע. החזקתי את הדמעות בתוך העיניים עד שההסעה הגיעה ואמא נכנסה למרפאה. כשראיתי את אמא הדמעות ירדו. עשו לי תפרים ורות'קה אומרת שמזל שנשארה לי עין. עכשיו יש לי גם את הסימן הקטן של כולנו בסנטר וגם סימן מתחת לעין. אני מיוחדת.", "pages": [{"page": 155, "src": "/assets/article/a04-scan-4-p155.webp", "w": 725, "h": 1244, "mark": [67.04, 90.51]}, {"page": 156, "src": "/assets/article/a04-scan-4-p156.webp", "w": 725, "h": 1244, "mark": [11.94, 18.05]}]}$n4$::jsonb
      WHEN e = $o5${"type": "scan", "src": "", "alt": "", "credit": "", "text": "אנחנו נכנסים לַבֵּיתֶלָדִים, צועדים בתהלוכה ישר לספסלים שבמקלחות. רות'קה מוציאה את התחבושות והיוד הסגול. כולנו מצטופפים סביב יפתח. הברכיים שלו פתוחות לגמרי. היוד ישרוף לו. אנחנו יודעים. רות'קה מנקה בעדינות. זה רק פצע. בסוף, כשהיא תסיים לחבוש את יפתח ולנגב לו את הפנים, היא תצייר לכולנו שעונים סגולים של יוד על היד."}$o5$::jsonb THEN $n5${"type": "scan", "src": "", "alt": "", "credit": "", "text": "אנחנו נכנסים לַבֵּיתֶלָדִים, צועדים בתהלוכה ישר לספסלים שבמקלחות. רות'קה מוציאה את התחבושות והיוד הסגול. כולנו מצטופפים סביב יפתח. הברכיים שלו פתוחות לגמרי. היוד ישרוף לו. אנחנו יודעים. רות'קה מנקה בעדינות. זה רק פצע. בסוף, כשהיא תסיים לחבוש את יפתח ולנגב לו את הפנים, היא תצייר לכולנו שעונים סגולים של יוד על היד.", "pages": [{"page": 156, "src": "/assets/article/a04-scan-5-p156.webp", "w": 725, "h": 1244, "mark": [18.05, 35.57]}]}$n5$::jsonb
      WHEN e = $o6${"type": "scan", "src": "", "alt": "", "credit": "", "text": "עוד עשר דקות כבר נחזור לעניינים הרגילים. לא קרה כלום."}$o6$::jsonb THEN $n6${"type": "scan", "src": "", "alt": "", "credit": "", "text": "עוד עשר דקות כבר נחזור לעניינים הרגילים. לא קרה כלום.", "pages": [{"page": 156, "src": "/assets/article/a04-scan-6-p156.webp", "w": 725, "h": 1244, "mark": [32.52, 38.99]}]}$n6$::jsonb
      ELSE e END
      ORDER BY o)
    FROM jsonb_array_elements(blocks) WITH ORDINALITY AS t(e, o)
